const ID_MAP = { breakfast: 'breakfast', lunch: 'lunch', dinner: 'dinner', grocery: 'grocery', baking: 'dessert', grooming: 'grooming', leisure: 'leisure', transit: 'transit', gift: 'gift' };
export const iconKeyOf = (cat) => {
  if (!cat) return 'add';
  if (cat.icon && PHOTO_ICONS[cat.icon]) return cat.icon;
  return ID_MAP[cat.id] || 'saving';
};
export function PhotoIcon({ name, size = 40, style }) {
  return <img src={PHOTO_ICONS[name] || PHOTO_ICONS.add} width={size} height={size} alt="" draggable={false} style={{ display: 'block', objectFit: 'contain', pointerEvents: 'none', userSelect: 'none', WebkitUserDrag: 'none', ...style }} />;
}
